<template>
  <section id="trade-exit-planner" class="exit-planner" tabindex="-1" aria-label="TP and SL after confirmation">
    <header class="exit-heading"><div><h3>Review TP/SL after confirmation</h3><p>Use the saved structural exits with your reported fill. Conditions and orders are not checked live.</p></div><span class="exit-state">{{ stateLabel }}</span></header>
    <p class="exit-note">Candidate TP1 must be at least 1.25R at the worst allowed fill, including entered costs. Exactly 1.25R is allowed.</p>
    <p v-if="!selected" class="exit-warning">The selected scenario is for reference only. Select a complete scenario that passes the TP1 ≥1.25R rule before reviewing exit calculations.</p>
    <template v-else>
      <label for="exit-plan-select" class="exit-select-label">Plan to review<select id="exit-plan-select" aria-label="Plan to review" v-model="selectedKey"><option v-for="option in options" :key="option.key" :value="option.key">{{ option.label }}</option></select></label>
      <p class="exit-trigger"><strong>Saved setup conditions:</strong> {{ selected?.plan.trigger }} <a href="#conditional-actions" @click.prevent="$emit('conditions',selectedKey)">Read the ordered scenario steps ↑</a></p>
      <div class="exit-reference"><div><span>Saved entry reference</span><strong>{{ price(selected?.plan.entry,basisFor('entry')) }}</strong></div><div><span>Saved structural SL</span><strong>{{ price(selected?.plan.stop,basisFor('stop')) }}</strong></div><div v-for="(target,index) in selected?.plan.targets||[]" :key="index"><span>{{ selected.plan.targets.length===1?'TP · only supported target':`TP${index+1} · saved target` }}</span><strong>{{ price(target,basisFor('targets',index)) }}</strong></div></div>
      <p v-if="selected?.plan.approximate||result.approximate" class="exit-note">≈ marks an estimate from the screenshot axis. Distances and R inherit that level uncertainty. Confirm precise levels against your current chart before using them.</p>
      <form class="exit-inputs" @submit.prevent>
        <div class="exit-input-grid"><label for="exit-entry">Actual entry / fill price<input id="exit-entry" v-model="inputs.entry" type="text" inputmode="decimal" autocomplete="off" spellcheck="false" :placeholder="String(selected?.plan.entry??'')" :disabled="Boolean(sourceIssue)" :aria-invalid="inputs.entry!==''&&!result.valid" aria-describedby="exit-entry-help"></label><label for="exit-costs">Additional round-trip costs (price units)<input id="exit-costs" v-model="inputs.costs" type="text" inputmode="decimal" autocomplete="off" spellcheck="false" placeholder="Blank = excluded; 0 is explicit zero" :disabled="Boolean(sourceIssue)" aria-describedby="exit-cost-help"></label><label v-if="selected?.plan.targets.length===2" for="exit-share">TP1 exit share (%)<input id="exit-share" v-model="inputs.tp1Share" type="text" inputmode="decimal" autocomplete="off" spellcheck="false" placeholder="Your assumption, e.g. 50" :disabled="Boolean(sourceIssue)" aria-describedby="exit-share-help"></label></div>
        <p id="exit-entry-help" class="exit-note">The saved entry is a reference, not an actual fill. Leave this field blank for reference preview.</p><p id="exit-cost-help" class="exit-note">Estimate additional aggregate costs in chart-price units, excluding costs already reflected in your fill. All comparisons are per price unit; no position size or account amount is assumed.</p><p v-if="selected?.plan.targets.length===2" id="exit-share-help" class="exit-note">The split is your what-if assumption, not a validated optimal allocation. Leave it blank to compare targets separately.</p>
        <label class="exit-confirmation"><input id="exit-confirmed" v-model="inputs.confirmed" type="checkbox" :disabled="Boolean(sourceIssue)||!inputs.entry.trim()" aria-label="I confirm the ordered setup conditions happened on my chart"><span>I confirm the ordered setup conditions happened on my chart<small>User-reported confirmation · not live or broker verified</small></span></label>
      </form>
      <div v-if="!result.valid" class="exit-warning" role="alert"><strong>Reassess before using these exits</strong><p v-for="error in result.errors" :key="error">{{ error }}</p></div>
      <template v-else>
        <p class="exit-calculation-context">{{ result.actual_entry_supplied?`Calculated from your entered price ${price(result.entry)}.`:`Reference preview using saved entry ${price(result.entry)}; no actual entry supplied.` }} {{ result.confirmation_user_reported?'You reported that the setup conditions happened.':'The setup remains unconfirmed in this planner.' }}</p>
        <div v-if="result.warnings.length" class="exit-warning" role="status"><strong>Payoff / explanation review required</strong><p v-for="warning in result.warnings" :key="warning">{{ warning }}</p></div>
        <dl class="exit-risk"><div><dt>Distance to saved stop</dt><dd>{{ quantity(result.risk) }}</dd><small>{{ percent(result.risk_percent) }} of entry price · gross</small></div><div v-if="result.costs_included"><dt>Estimated stop loss including additional costs</dt><dd>{{ quantity(result.adjusted_risk) }}</dd><small>{{ percent(result.adjusted_risk_percent) }} of entry price</small></div><div v-if="result.costs_included"><dt>Cost-aware break-even reference</dt><dd>{{ price(result.break_even) }}</dd><small>If all exposure exits at this one price; a reference, not a replacement stop.</small></div></dl>
        <div class="exit-table-wrap"><table><thead><tr><th>Saved exit</th><th>Price</th><th>Gross reward</th><th>Gross R</th><th v-if="result.costs_included">Reward after costs</th><th v-if="result.costs_included">R after costs</th></tr></thead><tbody><tr v-for="(target,index) in result.targets" :key="index"><th>{{ result.targets.length===1?'TP':`TP${index+1}` }}</th><td>{{ price(target.price,basisFor('targets',index)) }}</td><td>{{ quantity(target.reward) }}</td><td>{{ ratio(target.gross_r) }}</td><td v-if="result.costs_included">{{ quantity(target.adjusted_reward) }}</td><td v-if="result.costs_included">{{ ratio(target.adjusted_r) }}</td></tr></tbody></table></div>
        <p class="exit-note">{{ result.costs_included?'Cost-adjusted comparisons use your additional estimate once per original unit of exposure.':'Gross reward/risk excludes additional fees, spread and slippage.' }} R compares reward with the stop-loss distance, including additional costs when supplied.</p>
        <section v-if="result.allocation" class="exit-allocation"><h4>Your partial-exit what-if</h4><p>{{ percent(result.allocation.tp1_share*100) }} at TP1, {{ percent(result.allocation.remainder_share*100) }} at TP2. These portions are assumed, not recorded fills.</p><dl><div><dt>If both target portions fill at the saved prices</dt><dd>{{ quantity(result.allocation.weighted_reward) }} gross · {{ ratio(result.allocation.gross_r) }}</dd><small v-if="result.costs_included">{{ quantity(result.allocation.adjusted_reward) }} after additional costs · {{ ratio(result.allocation.adjusted_r) }}</small></div><div><dt>If TP1 fills, then the remainder exits at the saved stop</dt><dd>{{ quantity(result.allocation.tp1_then_stop_reward) }} gross · {{ ratio(result.allocation.tp1_then_stop_r) }}</dd><small v-if="result.costs_included">{{ quantity(result.allocation.tp1_then_stop_adjusted_reward) }} after additional costs · {{ ratio(result.allocation.tp1_then_stop_adjusted_r) }}</small></div></dl><p v-if="result.allocation.remainder_share>0">If TP1 fills, review the {{ percent(result.allocation.remainder_share*100) }} remainder against current structure, target obstacles and original invalidation. Remaining gross exposure to the saved stop is {{ quantity(result.allocation.remaining_stop_risk) }} per original unit.</p><p v-else>Your 100% TP1 assumption leaves no remaining portion for TP2.</p></section>
      </template>
      <section class="exit-structure"><h4>Why these exits, and what to review</h4><p><strong>SL / structural invalidation:</strong> {{ selected?.plan.level_reasons?.stop||selected?.plan.invalidation||'Review the saved chart invalidation.' }}</p><p v-if="selected?.plan.invalidation"><strong>If structure fails:</strong> {{ selected.plan.invalidation }} Review current structure and execution before changing an exit; saved prices remain fixed here.</p><p v-for="(reason,index) in selected?.plan.level_reasons?.targets||[]" :key="index"><strong>{{ selected.plan.targets.length===1?'Target obstacle':`TP${index+1} obstacle` }}:</strong> {{ reason }}</p><p v-if="selected?.plan.targets.length===2"><strong>After a possible TP1 fill:</strong> Review remaining exposure and the reaction at that obstacle. Check whether the original invalidation still fits; a later target depends on price actually reaching it.</p><p v-else><strong>Single-target plan:</strong> This chart provides one target. A second target needs fresh structural evidence.</p></section>
      <p class="exit-note">A stop is a reference/trigger, not a guaranteed execution price; actual losses can exceed this estimate. <a href="https://www.finra.org/investors/insights/stop-orders-factors-consider-during-volatile-markets" target="_blank" rel="noopener noreferrer">Stop execution guidance</a>.</p>
    </template>
    <p class="exit-session-note">Inputs are session-only and never change the saved report. Refresh, leave this view, change report/setup or update its source evidence to reset your fill and confirmation.</p>
  </section>
</template>
<script setup>
import {computed,ref,watch} from 'vue'
import {exitPlanOptions,exitResetToken,exitPlanSourceIssue,calculateTradeExit,freshExitInputs} from '../utils/tradeExitPlan.mjs'
import {chartScenarioOptions} from '../utils/chartWorkspace.mjs'
const props=defineProps({run:{type:Object,required:true}})
const selectedKey=defineModel('planKey',{default:''})
defineEmits(['conditions'])
const options=computed(()=>exitPlanOptions(props.run)),inputs=ref(freshExitInputs())
watch(()=>options.value.map(option=>option.key).join('|'),()=>{if(chartScenarioOptions(props.run).some(option=>option.key===selectedKey.value))return;if(!options.value.some(option=>option.key===selectedKey.value))selectedKey.value=options.value[0]?.key||''},{immediate:true,flush:'sync'})
const selected=computed(()=>options.value.find(option=>option.key===selectedKey.value))
const sourceIssue=computed(()=>exitPlanSourceIssue(props.run,selected.value))
watch(()=>exitResetToken(props.run,selectedKey.value),()=>{inputs.value=freshExitInputs()},{flush:'sync'})
const result=computed(()=>calculateTradeExit(props.run,selectedKey.value,inputs.value))
const stateLabel=computed(()=>!result.value.valid?'Reassess':result.value.review_required?'Review required':result.value.confirmation_user_reported?'User-confirmed management math':result.value.actual_entry_supplied?'Entry preview · confirmation pending':'Saved reference preview')
function selectPlan(key){if(!options.value.some(option=>option.key===key))return false;selectedKey.value=key;return true}
defineExpose({selectPlan})
function basisFor(kind,index=0){const plan=selected.value?.plan;if(!plan)return null;const stored=kind==='targets'?plan.level_bases?.targets?.[index]:plan.level_bases?.[kind];const id=kind==='targets'?plan.target_level_ids?.[index]:kind==='entry'?plan.entry_level_id:plan.stop_level_id;return stored||(props.run.observation?.levels||[]).find(level=>level.id===id)?.basis}
const quantity=value=>Number.isFinite(value)?Number(value).toLocaleString('en-US',{maximumSignificantDigits:8}):'Not established'
const price=(value,basis)=>(basis==='axis_estimate'?'≈ ':'')+quantity(value)
const percent=value=>Number.isFinite(value)?`${Number(value.toFixed(3))}%`:'Not established'
const ratio=value=>Number.isFinite(value)?`${Number(value.toFixed(3))}R`:'Not established'
</script>
<style scoped>
