-size:10px;color:#7f8a98;margin-top:4px}.exit-warning{border-left:2px solid #c8865b;background:#fff8f3;padding:13px 16px;margin:17px 0;font-size:12px;line-height:1.75;color:#845d40}.exit-warning strong{font-weight:500}.exit-warning p{margin:7px 0}.exit-calculation-context{font-size:12px;line-height:1.7;color:#657284}.exit-risk{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;padding:18px 0;margin:13px 0}.exit-risk dt{font-size:11px;color:#74808f;line-height:1.6}.exit-risk dd{font-size:24px;line-height:1.5;letter-spacing:-.5px;margin:6px 0;font-variant-numeric:tabular-nums}.exit-risk small{font-size:10px;color:#7d8896;line-height:1.65;display:block}.exit-table-wrap{overflow:auto}.exit-table-wrap table{width:100%;border-collapse:collapse;font-size:12px;text-align:left;font-variant-numeric:tabular-nums}.exit-table-wrap th,.exit-table-wrap td{padding:11px 12px 11px 0;border-bottom:1px solid #e4e9ef;white-space:nowrap}.exit-table-wrap th{font-weight:500;color:#74808f;font-size:11px}.exit-allocation,.exit-structure{border-top:1px solid #e5eaf0;padding-top:18px;margin-top:23px;font-size:12px;line-height:1.8;color:#647385}.exit-allocation h4,.exit-structure h4{font-size:15px;font-weight:500;color:#344151;margin:0 0 11px}.exit-allocation p,.exit-structure p{margin:9px 0}.exit-allocation dl{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:15px 0}.exit-allocation dt{font-size:11px;color:#748090}.exit-allocation dd{font-size:16px;margin:6px 0;color:#485768;font-variant-numeric:tabular-nums}.exit-allocation small{font-size:11px;color:#7f8a98}.exit-session-note{border-top:1px solid #e7ebf0;padding-top:12px;margin-top:22px}.exit-planner:focus{outline:none}.exit-planner a:focus-visible,.exit-planner input:focus-visible,.exit-planner select:focus-visible{outline:2px solid #ad420f;outline-offset:3px}@media(max-width:700px){.exit-heading{flex-direction:column;gap:10px}.exit-reference{grid-template-columns:1fr 1fr;gap:18px}.exit-input-grid,.exit-risk,.exit-allocation dl{grid-template-columns:1fr;gap:16px}.exit-heading h3{font-size:21px}.exit-table-wrap table{min-width:420px}.exit-reference strong{font-size:21px}.exit-state{max-width:100%;flex-shrink:1}}
</style>
